cd /home/user/myproject
cat > verify.gd <<EOF
extends SceneTree

func _ready() -> void:
	var scn = load("res://main.tscn")
	var node = scn.instantiate()
	root.add_child(node)
	await RenderingServer.frame_post_draw

	var vp: SubViewport = node.get_node("World/SourceViewport")
	var tex: ViewportTexture = vp.get_texture()

	var cases = [
		{"pos": Vector3(3, 0, 5), "basis": Basis.IDENTITY, "check": "red"},
		{"pos": Vector3(-3, 0, 5), "basis": Basis.IDENTITY, "check": "green"},
		{"pos": Vector3(0, 0, -8), "basis": Basis.from_euler(Vector3(0, PI, 0)), "check": "blue"}
	]

	var all_pass = true
	for c in cases:
		node.set_camera_pose(c["pos"], c["basis"])
		await RenderingServer.frame_post_draw
		await RenderingServer.frame_post_draw

		var img = tex.get_image()
		# img.save_png("test_" + c["check"] + ".png")

		var center = img.get_pixel(128, 128)
		print("pose: ", c["pos"], " center: ", center)

		if c["check"] == "red":
			if not (center.r >= 0.8 and center.g <= 0.2 and center.b <= 0.2):
				print("FAIL red")
				all_pass = false
		elif c["check"] == "green":
			if not (center.g >= 0.8 and center.r <= 0.2 and center.b <= 0.2):
				print("FAIL green")
				all_pass = false
		elif c["check"] == "blue":
			if not (center.b >= 0.8 and center.r <= 0.2 and center.g <= 0.2):
				print("FAIL blue")
				all_pass = false

		var corner = img.get_pixel(8, 8)
		print(" corner: ", corner)
		if corner.r <= 0.1 and corner.g <= 0.1 and corner.b <= 0.1:
			print(" background black OK")

	if all_pass:
		print("ALL CASES PASS")
		quit(0)
	else:
		print("FAIL")
		quit(1)
EOF
godot --headless -s verify.gd

